package com.bankgearslots;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.SpritePixels;
import net.runelite.api.gameval.SpriteID;
import org.junit.Test;

public class BankSlotTextureManagerTest
{
	@Test
	public void mapsSlotTypesToResourcePackSpriteIds()
	{
		assertEquals(SpriteID.Wornicons.HEAD, BankSlotType.HEAD.getSpriteId());
		assertEquals(SpriteID.Wornicons.CAPE, BankSlotType.CAPE.getSpriteId());
		assertEquals(SpriteID.Wornicons.NECK, BankSlotType.NECK.getSpriteId());
		assertEquals(SpriteID.Wornicons.WEAPON, BankSlotType.WEAPON.getSpriteId());
		assertEquals(SpriteID.Wornicons.WEAPON, BankSlotType.TWO_HANDED.getSpriteId());
		assertEquals(SpriteID.Wornicons.TORSO, BankSlotType.BODY.getSpriteId());
		assertEquals(SpriteID.Wornicons.SHIELD, BankSlotType.SHIELD.getSpriteId());
		assertEquals(SpriteID.Wornicons.LEGS, BankSlotType.LEGS.getSpriteId());
		assertEquals(SpriteID.Wornicons.HANDS, BankSlotType.HANDS.getSpriteId());
		assertEquals(SpriteID.Wornicons.FEET, BankSlotType.FEET.getSpriteId());
		assertEquals(SpriteID.Wornicons.RING, BankSlotType.RING.getSpriteId());
		assertEquals(SpriteID.Wornicons.AMMUNITION, BankSlotType.AMMUNITION.getSpriteId());
		assertEquals(-1, BankSlotType.EMPTY_SLOT.getSpriteId());
	}

	@Test
	public void usesBundledTextureWithoutOverrides()
	{
		Map<Integer, SpritePixels> overrides = new HashMap<>();
		BankSlotTextureManager manager = new BankSlotTextureManager(
			() -> overrides,
			spriteId -> null);

		assertSame(BankSlotType.HEAD.getFallbackTexture(), manager.getTexture(BankSlotType.HEAD));
	}

	@Test
	public void composesPackTileWithNativeGlyphForPartialPack()
	{
		Map<Integer, SpritePixels> overrides = new HashMap<>();
		overrides.put(SpriteID.Miscgraphics.EQUIPMENT_SLOT_TILE, sprite(image(4, 4, Color.RED)));
		BufferedImage nativeHead = image(2, 2, Color.BLUE);
		BankSlotTextureManager manager = new BankSlotTextureManager(
			() -> overrides,
			spriteId -> spriteId == SpriteID.Wornicons.HEAD ? nativeHead : null);

		BufferedImage texture = manager.getTexture(BankSlotType.HEAD);

		assertEquals(Color.RED.getRGB(), texture.getRGB(0, 0));
		assertEquals(Color.BLUE.getRGB(), texture.getRGB(1, 1));
		assertEquals(Color.BLUE.getRGB(), texture.getRGB(2, 2));
	}

	@Test
	public void composesPackGlyphWithNativeTileForPartialPack()
	{
		Map<Integer, SpritePixels> overrides = new HashMap<>();
		overrides.put(SpriteID.Wornicons.HEAD, sprite(image(2, 2, Color.MAGENTA)));
		BufferedImage nativeTile = image(4, 4, Color.CYAN);
		BankSlotTextureManager manager = new BankSlotTextureManager(
			() -> overrides,
			spriteId -> spriteId == SpriteID.Miscgraphics.EQUIPMENT_SLOT_TILE ? nativeTile : null);

		BufferedImage texture = manager.getTexture(BankSlotType.HEAD);

		assertEquals(4, texture.getWidth());
		assertEquals(4, texture.getHeight());
		assertEquals(Color.CYAN.getRGB(), texture.getRGB(0, 0));
		assertEquals(Color.MAGENTA.getRGB(), texture.getRGB(1, 1));
		assertEquals(Color.MAGENTA.getRGB(), texture.getRGB(2, 2));
	}

	@Test
	public void fallsBackToBundledTileWhenNativeTileIsUnavailable()
	{
		Map<Integer, SpritePixels> overrides = new HashMap<>();
		overrides.put(SpriteID.Wornicons.HEAD, sprite(image(2, 2, Color.MAGENTA)));
		BufferedImage[] nativeTile = new BufferedImage[1];
		BankSlotTextureManager manager = new BankSlotTextureManager(
			() -> overrides,
			spriteId -> nativeTile[0]);

		BufferedImage fallback = manager.getTexture(BankSlotType.HEAD);

		assertEquals(36, fallback.getWidth());
		assertEquals(36, fallback.getHeight());
		assertEquals(Color.MAGENTA.getRGB(), fallback.getRGB(17, 17));
		assertEquals(Color.MAGENTA.getRGB(), fallback.getRGB(18, 18));

		nativeTile[0] = image(4, 4, Color.CYAN);
		BufferedImage recovered = manager.getTexture(BankSlotType.HEAD);

		assertEquals(4, recovered.getWidth());
		assertEquals(Color.CYAN.getRGB(), recovered.getRGB(0, 0));
	}

	@Test
	public void refreshesCachedTextureWhenPackChangesOrIsRemoved()
	{
		Map<Integer, SpritePixels> overrides = new HashMap<>();
		overrides.put(SpriteID.Miscgraphics.EQUIPMENT_SLOT_TILE, sprite(image(4, 4, Color.RED)));
		overrides.put(SpriteID.Wornicons.HEAD, sprite(image(2, 2, Color.BLUE)));
		BankSlotTextureManager manager = new BankSlotTextureManager(
			() -> overrides,
			spriteId -> null);

		BufferedImage first = manager.getTexture(BankSlotType.HEAD);
		assertSame(first, manager.getTexture(BankSlotType.HEAD));

		overrides.put(SpriteID.Miscgraphics.EQUIPMENT_SLOT_TILE, sprite(image(4, 4, Color.YELLOW)));
		BufferedImage second = manager.getTexture(BankSlotType.HEAD);

		assertNotSame(first, second);
		assertEquals(Color.YELLOW.getRGB(), second.getRGB(0, 0));

		overrides.put(SpriteID.Wornicons.HEAD, sprite(image(2, 2, Color.GREEN)));
		BufferedImage third = manager.getTexture(BankSlotType.HEAD);

		assertNotSame(second, third);
		assertEquals(Color.GREEN.getRGB(), third.getRGB(1, 1));

		overrides.clear();

		assertSame(BankSlotType.HEAD.getFallbackTexture(), manager.getTexture(BankSlotType.HEAD));
	}

	@Test
	public void usesPackTileForEmptySlots()
	{
		Map<Integer, SpritePixels> overrides = new HashMap<>();
		BufferedImage tile = image(4, 4, Color.ORANGE);
		overrides.put(SpriteID.Miscgraphics.EQUIPMENT_SLOT_TILE, sprite(tile));
		BankSlotTextureManager manager = new BankSlotTextureManager(
			() -> overrides,
			spriteId -> null);

		BufferedImage texture = manager.getTexture(BankSlotType.EMPTY_SLOT);

		assertEquals(Color.ORANGE.getRGB(), texture.getRGB(0, 0));
		assertEquals(Color.ORANGE.getRGB(), texture.getRGB(3, 3));
	}

	@Test
	public void mirrorsPackWeaponGlyphForTwoHandedSlots()
	{
		Map<Integer, SpritePixels> overrides = new HashMap<>();
		overrides.put(SpriteID.Miscgraphics.EQUIPMENT_SLOT_TILE, sprite(image(4, 4, Color.RED)));
		BufferedImage weapon = new BufferedImage(2, 2, BufferedImage.TYPE_INT_ARGB);
		weapon.setRGB(0, 0, Color.BLUE.getRGB());
		overrides.put(SpriteID.Wornicons.WEAPON, sprite(weapon));
		BankSlotTextureManager manager = new BankSlotTextureManager(
			() -> overrides,
			spriteId -> null);

		BufferedImage texture = manager.getTexture(BankSlotType.TWO_HANDED);

		assertEquals(Color.BLUE.getRGB(), texture.getRGB(1, 1));
		assertEquals(Color.BLUE.getRGB(), texture.getRGB(2, 1));
	}

	private static BufferedImage image(int width, int height, Color color)
	{
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setColor(color);
			graphics.fillRect(0, 0, width, height);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static SpritePixels sprite(BufferedImage image)
	{
		return new TestSpritePixels(image);
	}

	private static final class TestSpritePixels implements SpritePixels
	{
		private final BufferedImage image;
		private int maxWidth;
		private int maxHeight;
		private int offsetX;
		private int offsetY;

		private TestSpritePixels(BufferedImage image)
		{
			this.image = image;
			maxWidth = image.getWidth();
			maxHeight = image.getHeight();
		}

		@Override
		public void drawAt(int x, int y)
		{
		}

		@Override
		public int getWidth()
		{
			return image.getWidth();
		}

		@Override
		public int getHeight()
		{
			return image.getHeight();
		}

		@Override
		public int getMaxWidth()
		{
			return maxWidth;
		}

		@Override
		public int getMaxHeight()
		{
			return maxHeight;
		}

		@Override
		public int getOffsetX()
		{
			return offsetX;
		}

		@Override
		public int getOffsetY()
		{
			return offsetY;
		}

		@Override
		public void setMaxWidth(int maxWidth)
		{
			this.maxWidth = maxWidth;
		}

		@Override
		public void setMaxHeight(int maxHeight)
		{
			this.maxHeight = maxHeight;
		}

		@Override
		public void setOffsetX(int offsetX)
		{
			this.offsetX = offsetX;
		}

		@Override
		public void setOffsetY(int offsetY)
		{
			this.offsetY = offsetY;
		}

		@Override
		public int[] getPixels()
		{
			return image.getRGB(0, 0, image.getWidth(), image.getHeight(), null, 0, image.getWidth());
		}

		@Override
		public BufferedImage toBufferedImage()
		{
			return image;
		}

		@Override
		public void toBufferedImage(BufferedImage target)
		{
			Graphics2D graphics = target.createGraphics();
			try
			{
				graphics.drawImage(image, 0, 0, null);
			}
			finally
			{
				graphics.dispose();
			}
		}

		@Override
		public BufferedImage toBufferedOutline(Color color)
		{
			return image;
		}

		@Override
		public void toBufferedOutline(BufferedImage target, int color)
		{
			toBufferedImage(target);
		}
	}
}

