package com.bankgearslots;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import org.junit.Test;

public class BankSlotTypeTest
{
	@Test
	public void blackTintPreservesTextureBrightnessDifferences()
	{
		int dark = BankSlotType.tintPixel(new Color(80, 80, 80, 180).getRGB(), new Color(0, 0, 0, 255));
		int bright = BankSlotType.tintPixel(new Color(200, 200, 200, 180).getRGB(), new Color(0, 0, 0, 255));

		assertEquals(180, alpha(dark));
		assertEquals(180, alpha(bright));
		assertTrue(red(dark) < 80);
		assertTrue(red(bright) > red(dark));
		assertEquals(red(dark), green(dark));
		assertEquals(green(dark), blue(dark));
	}

	@Test
	public void whiteTintBrightensWhilePreservingTextureBrightnessDifferences()
	{
		int dark = BankSlotType.tintPixel(new Color(80, 80, 80, 180).getRGB(), Color.WHITE);
		int bright = BankSlotType.tintPixel(new Color(200, 200, 200, 180).getRGB(), Color.WHITE);

		assertEquals(180, alpha(dark));
		assertEquals(180, alpha(bright));
		assertTrue(red(dark) > 80);
		assertTrue(red(bright) > red(dark));
		assertEquals(red(dark), green(dark));
		assertEquals(green(dark), blue(dark));
	}

	@Test
	public void transparentTintLeavesPixelUnchanged()
	{
		int source = new Color(120, 80, 40, 200).getRGB();

		assertEquals(source, BankSlotType.tintPixel(source, new Color(0, 0, 0, 0)));
	}

	@Test
	public void colorTintPreservesSourceAlpha()
	{
		int source = new Color(160, 160, 160, 123).getRGB();
		int tinted = BankSlotType.tintPixel(source, new Color(255, 0, 0, 255));

		assertEquals(123, alpha(tinted));
		assertTrue(red(tinted) > green(tinted));
		assertEquals(green(tinted), blue(tinted));
	}

	@Test
	public void fullBlueTintDoesNotFlattenTextureIntoPureBlue()
	{
		int dark = BankSlotType.tintPixel(new Color(80, 80, 80, 255).getRGB(), Color.BLUE);
		int bright = BankSlotType.tintPixel(new Color(200, 200, 200, 255).getRGB(), Color.BLUE);

		assertTrue(blue(bright) > blue(dark));
		assertTrue(blue(dark) > red(dark));
		assertTrue(blue(dark) > green(dark));
		assertTrue(blue(dark) < 255);
		assertTrue(bright != dark);
	}

	@Test
	public void partialTintBlendsBetweenSourceAndColorizedTexture()
	{
		int source = new Color(120, 120, 120, 255).getRGB();
		int tinted = BankSlotType.tintPixel(source, new Color(0, 0, 255, 128));

		assertTrue(blue(tinted) > red(tinted));
		assertTrue(red(tinted) > 0);
	}

	@Test
	public void tintedTextureCacheRefreshesWhenSourceTextureChanges()
	{
		BufferedImage dark = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		dark.setRGB(0, 0, new Color(40, 40, 40).getRGB());
		BufferedImage bright = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		bright.setRGB(0, 0, new Color(220, 220, 220).getRGB());

		int darkTinted = renderTintedPixel(dark, Color.BLUE);
		int brightTinted = renderTintedPixel(bright, Color.BLUE);

		assertNotEquals(darkTinted, brightTinted);
		assertTrue(blue(brightTinted) > blue(darkTinted));
	}

	private static int renderTintedPixel(BufferedImage source, Color tint)
	{
		BufferedImage target = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = target.createGraphics();
		try
		{
			BankSlotType.HEAD.render(graphics, new Rectangle(0, 0, 1, 1), source, 1, 255, tint);
		}
		finally
		{
			graphics.dispose();
		}
		return target.getRGB(0, 0);
	}

	private static int alpha(int argb)
	{
		return argb >>> 24;
	}

	private static int red(int argb)
	{
		return (argb >>> 16) & 0xFF;
	}

	private static int green(int argb)
	{
		return (argb >>> 8) & 0xFF;
	}

	private static int blue(int argb)
	{
		return argb & 0xFF;
	}
}

package com.bankgearslots;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.awt.Color;
import java.util.List;
import org.junit.Test;

public class BankSlotRuleTest
{
	@Test
	public void resolvesSpecificTagRules()
	{
		List<BankSlotRule> rules = BankSlotRule.parseRules("mining,combat:42:legs");

		assertEquals(BankSlotType.LEGS, resolveType(rules, new BankSlotTarget("mining", 42, true, -1)));
		assertEquals(BankSlotType.LEGS, resolveType(rules, new BankSlotTarget("combat", 42, true, -1)));
		assertNull(resolveType(rules, new BankSlotTarget("skilling", 42, true, -1)));
	}

	@Test
	public void laterRulesOverrideEarlierRules()
	{
		List<BankSlotRule> rules = BankSlotRule.parseRules("*:31:head\nmining:31:cape\ncombat:31:none");

		assertEquals(BankSlotType.CAPE, resolveType(rules, new BankSlotTarget("mining", 31, true, -1)));
		assertNull(resolveType(rules, new BankSlotTarget("combat", 31, true, -1)));
		assertEquals(BankSlotType.HEAD, resolveType(rules, new BankSlotTarget("BANK_0", 31, false, 0)));
	}

	@Test
	public void resolvesHardcodedSelectors()
	{
		List<BankSlotRule> rules = BankSlotRule.parseRules("BANK:3:ring\nTAGS:3:ammunition\nBANK_2:3:two_handed");

		assertEquals(BankSlotType.RING, resolveType(rules, new BankSlotTarget("BANK_0", 3, false, 0)));
		assertEquals(BankSlotType.TWO_HANDED, resolveType(rules, new BankSlotTarget("BANK_2", 3, false, 2)));
		assertEquals(BankSlotType.AMMUNITION, resolveType(rules, new BankSlotTarget("mining", 3, true, -1)));
	}

	@Test
	public void resolvesRanges()
	{
		List<BankSlotRule> rules = BankSlotRule.parseRules("herblore:25-44,47=85:empty_slot");

		assertEquals(BankSlotType.EMPTY_SLOT, resolveType(rules, new BankSlotTarget("herblore", 25, true, -1)));
		assertEquals(BankSlotType.EMPTY_SLOT, resolveType(rules, new BankSlotTarget("herblore", 44, true, -1)));
		assertNull(resolveType(rules, new BankSlotTarget("herblore", 46, true, -1)));
		assertEquals(BankSlotType.EMPTY_SLOT, resolveType(rules, new BankSlotTarget("herblore", 85, true, -1)));
	}

	@Test
	public void resolvesWildcardCells()
	{
		List<BankSlotRule> rules = BankSlotRule.parseRules("farming:*:head");

		assertEquals(BankSlotType.HEAD, resolveType(rules, new BankSlotTarget("farming", 0, true, -1)));
		assertEquals(BankSlotType.HEAD, resolveType(rules, new BankSlotTarget("farming", 999, true, -1)));
		assertNull(resolveType(rules, new BankSlotTarget("mining", 999, true, -1)));
	}

	@Test
	public void wildcardCellRulesCanClearAllCellsForASelector()
	{
		List<BankSlotRule> rules = BankSlotRule.parseRules("*:31:head\nfarming:*:none");

		assertNull(resolveType(rules, new BankSlotTarget("farming", 31, true, -1)));
		assertEquals(BankSlotType.HEAD, resolveType(rules, new BankSlotTarget("mining", 31, true, -1)));
	}

	@Test
	public void resolvesTintedStyles()
	{
		List<BankSlotRule> rules = BankSlotRule.parseRules("herblore:31:head:#52530095");
		BankSlotStyle style = BankSlotRule.resolve(rules, new BankSlotTarget("herblore", 31, true, -1));

		assertEquals(BankSlotType.HEAD, style.getType());
		assertEquals(new Color(0x52, 0x53, 0x00, 0x95), style.getTint());
	}

	@Test
	public void ignoresInvalidTypeNames()
	{
		List<BankSlotRule> rules = BankSlotRule.parseRules("BANK_1:31:helmet\nBANK_1:32:empty\nBANK_1:33:two handed");

		assertNull(resolveType(rules, new BankSlotTarget("BANK_1", 31, false, 1)));
		assertNull(resolveType(rules, new BankSlotTarget("BANK_1", 32, false, 1)));
		assertNull(resolveType(rules, new BankSlotTarget("BANK_1", 33, false, 1)));
	}

	private static BankSlotType resolveType(List<BankSlotRule> rules, BankSlotTarget target)
	{
		BankSlotStyle style = BankSlotRule.resolve(rules, target);
		return style == null ? null : style.getType();
	}
}

package com.bankgearslots;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertNotNull;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.net.URL;
import javax.imageio.ImageIO;
import org.junit.Test;

public class BankSlotTextureResourceTest
{
	@Test
	public void loadsSlotTextures() throws IOException
	{
		for (BankSlotType type : BankSlotType.values())
		{
			URL resource = BankSlotType.class.getResource(type.getTextureResource());
			assertNotNull(type.getConfigKey(), resource);

			BufferedImage image = ImageIO.read(resource);
			assertNotNull(type.getConfigKey(), image);
			assertEquals(type.getConfigKey(), image.getWidth(), image.getHeight());
			assertTrue(type.getConfigKey(), image.getWidth() > 0);
		}
	}
}

package com.bankgearslots;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.ItemID;
import org.junit.Test;

public class BankGearSlotsPluginBehaviorTest
{
	@Test
	public void rendersEmptySlotTextureForOccupiedAssignedCells()
	{
		assertEquals(BankSlotType.EMPTY_SLOT, BankGearSlotsPlugin.getRenderedSlotType(BankSlotType.HEAD, ItemID.ABYSSAL_WHIP));
	}

	@Test
	public void preservesTintWhenOccupiedCellsRenderAsEmptySlots()
	{
		BankSlotStyle rendered = BankGearSlotsPlugin.getRenderedSlotStyle(
			BankSlotStyle.of(BankSlotType.HEAD, new Color(0x52, 0x53, 0x00, 0x95)),
			ItemID.ABYSSAL_WHIP,
			false);

		assertEquals(BankSlotType.EMPTY_SLOT, rendered.getType());
		assertEquals(new Color(0x52, 0x53, 0x00, 0x95), rendered.getTint());
	}

	@Test
	public void rendersAssignedTextureWhileOccupiedCellIsDragged()
	{
		assertEquals(BankSlotType.HEAD, BankGearSlotsPlugin.getRenderedSlotType(BankSlotType.HEAD, ItemID.ABYSSAL_WHIP, true));
	}

	@Test
	public void keepsAssignedTextureForEmptyOrFillerCells()
	{
		assertEquals(BankSlotType.HEAD, BankGearSlotsPlugin.getRenderedSlotType(BankSlotType.HEAD, -1));
		assertEquals(BankSlotType.HEAD, BankGearSlotsPlugin.getRenderedSlotType(BankSlotType.HEAD, 0));
		assertEquals(BankSlotType.HEAD, BankGearSlotsPlugin.getRenderedSlotType(BankSlotType.HEAD, ItemID.BANK_FILLER));
	}

	@Test
	public void doesNotRenderUnassignedOccupiedCells()
	{
		assertNull(BankGearSlotsPlugin.getRenderedSlotType(null, ItemID.ABYSSAL_WHIP));
	}

	@Test
	public void detectsRealBankItemIds()
	{
		assertTrue(BankGearSlotsPlugin.isRealBankItemId(ItemID.ABYSSAL_WHIP));
		assertFalse(BankGearSlotsPlugin.isRealBankItemId(-1));
		assertFalse(BankGearSlotsPlugin.isRealBankItemId(0));
		assertFalse(BankGearSlotsPlugin.isRealBankItemId(ItemID.BANK_FILLER));
	}

	@Test
	public void labelsAssignedCellsAsModifySlot()
	{
		assertEquals("Add Slot", BankGearSlotsPlugin.getSlotMenuOption(null));
		assertEquals("Modify Slot", BankGearSlotsPlugin.getSlotMenuOption(BankSlotStyle.of(BankSlotType.HEAD)));
	}

	@Test
	public void requiresShiftForSlotMenuByDefault()
	{
		BankGearSlotsConfig config = new BankGearSlotsConfig()
		{
		};

		assertTrue(config.requireShift());
		assertFalse(BankGearSlotsPlugin.shouldShowSlotMenu(false, config.requireShift(), false));
		assertTrue(BankGearSlotsPlugin.shouldShowSlotMenu(false, config.requireShift(), true));
	}

	@Test
	public void showsSlotMenuWithoutShiftWhenRequirementIsDisabled()
	{
		assertTrue(BankGearSlotsPlugin.shouldShowSlotMenu(false, false, false));
		assertTrue(BankGearSlotsPlugin.shouldShowSlotMenu(false, false, true));
		assertFalse(BankGearSlotsPlugin.shouldShowSlotMenu(true, false, true));
	}

	@Test
	public void usesCanonicalBankTagsServiceNamesForTagTargets()
	{
		assertTagTarget("herblore", 29, BankGearSlotsPlugin.createBankTagCellResolver("herblore").targetForCell(29));
		assertTagTarget("gear (1.2m)", 4, BankGearSlotsPlugin.createBankTagCellResolver("gear (1.2m)").targetForCell(4));
		assertTagTarget("tab", 7, BankGearSlotsPlugin.createBankTagCellResolver("tab").targetForCell(7));
		assertNull(BankGearSlotsPlugin.createBankTagCellResolver("tagtabs").targetForCell(0));
	}

	@Test
	public void migratesLegacyGeAndHaDecoratedTagRules()
	{
		String rules =
			"herblore (ge: 4,912) (ha: 2,692):29:head\n" +
			"herblore (ge: 4,912) (ha: 2,692):36:head\n" +
			"herblore (ge: 4,912) (ha: 2,692):37:head\n" +
			"gear (GE:4.9K) (HA:2.7k):4:ring\n" +
			"loot (HA:2.14b):5:cape";

		String migrated = BankGearSlotsPlugin.migrateLegacyTagValueRules(rules);

		assertEquals(
			"herblore:29:head\n" +
