package com.bankgearslots;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

final class BankSlotCells
{
	private static final String WILDCARD = "*";

	private BankSlotCells()
	{
	}

	static List<CellRange> parse(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return Collections.emptyList();
		}

		List<CellRange> ranges = new ArrayList<>();
		for (String part : value.split(","))
		{
			CellRange range = parsePart(part.trim());
			if (range != null)
			{
				if (range.wildcard)
				{
					return Collections.singletonList(range);
				}
				ranges.add(range);
			}
		}
		return normalize(ranges);
	}

	static boolean contains(List<CellRange> ranges, int cell)
	{
		for (CellRange range : ranges)
		{
			if (range.contains(cell))
			{
				return true;
			}
		}
		return false;
	}

	static boolean contains(String value, int cell)
	{
		return contains(parse(value), cell);
	}

	static String canonicalize(String value)
	{
		return format(parse(value));
	}

	static boolean isWildcard(String value)
	{
		List<CellRange> ranges = parse(value);
		return ranges.size() == 1 && ranges.get(0).wildcard;
	}

	static String single(int cell)
	{
		return Integer.toString(cell);
	}

	static String removeCell(String value, int cell)
	{
		if (isWildcard(value))
		{
			return WILDCARD;
		}

		List<CellRange> remaining = new ArrayList<>();
		for (CellRange range : parse(value))
		{
			if (!range.contains(cell))
			{
				remaining.add(range);
			}
			else
			{
				if (cell > range.start)
				{
					remaining.add(new CellRange(range.start, cell - 1));
				}
				if (cell < range.end)
				{
					remaining.add(new CellRange(cell + 1, range.end));
				}
			}
		}

		return remaining.isEmpty() ? null : format(normalize(remaining));
	}

	static String format(List<CellRange> ranges)
	{
		StringBuilder builder = new StringBuilder();
		for (CellRange range : ranges)
		{
			if (range.wildcard)
			{
				return WILDCARD;
			}
			if (builder.length() > 0)
			{
				builder.append(',');
			}
			builder.append(range.start);
			if (range.start != range.end)
			{
				builder.append('-').append(range.end);
			}
		}
		return builder.toString();
	}

	private static CellRange parsePart(String value)
	{
		if (value.isEmpty())
		{
			return null;
		}
		if (WILDCARD.equals(value))
		{
			return CellRange.wildcard();
		}

		int separator = value.indexOf('-');
		if (separator < 0)
		{
			separator = value.indexOf('=');
		}

		try
		{
			if (separator < 0)
			{
				int cell = Integer.parseInt(value);
				return cell < 0 ? null : new CellRange(cell, cell);
			}

			int start = Integer.parseInt(value.substring(0, separator).trim());
			int end = Integer.parseInt(value.substring(separator + 1).trim());
			if (start < 0 || end < 0)
			{
				return null;
			}
			return new CellRange(Math.min(start, end), Math.max(start, end));
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	private static List<CellRange> normalize(List<CellRange> ranges)
	{
		if (ranges.isEmpty())
		{
			return ranges;
		}
		for (CellRange range : ranges)
		{
			if (range.wildcard)
			{
				return Collections.singletonList(range);
			}
		}

		ranges.sort(Comparator.comparingInt(range -> range.start));
		List<CellRange> normalized = new ArrayList<>();
		for (CellRange range : ranges)
		{
			if (normalized.isEmpty())
			{
				normalized.add(range);
				continue;
			}

			CellRange last = normalized.get(normalized.size() - 1);
			if (range.start <= last.end + 1)
			{
				normalized.set(normalized.size() - 1, new CellRange(last.start, Math.max(last.end, range.end)));
			}
			else
			{
				normalized.add(range);
			}
		}
		return normalized;
	}

	static final class CellRange
	{
		private final int start;
		private final int end;
		private final boolean wildcard;

		private CellRange(int start, int end)
		{
			this(start, end, false);
		}

		private CellRange(int start, int end, boolean wildcard)
		{
			this.start = start;
			this.end = end;
			this.wildcard = wildcard;
		}

		private static CellRange wildcard()
		{
			return new CellRange(0, Integer.MAX_VALUE, true);
		}

		private boolean contains(int cell)
		{
			return cell >= start && cell <= end;
		}
	}
}

package com.bankgearslots;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.client.util.Text;

final class BankSlotRule
{
	static final String WILDCARD = "*";
	static final String BANK = "bank";
	static final String TAGS = "tags";
	private static final String NONE = "none";

	private final List<String> selectors;
	private final List<BankSlotCells.CellRange> cells;
	private final BankSlotStyle style;

	private BankSlotRule(List<String> selectors, List<BankSlotCells.CellRange> cells, BankSlotStyle style)
	{
		this.selectors = selectors;
		this.cells = cells;
		this.style = style;
	}

	static List<BankSlotRule> parseRules(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return Collections.emptyList();
		}

		List<BankSlotRule> rules = new ArrayList<>();
		for (String line : value.split("\\R"))
		{
			BankSlotRule rule = parse(line);
			if (rule != null)
			{
				rules.add(rule);
			}
		}
		return rules;
	}

	static BankSlotRule parse(String line)
	{
		if (line == null)
		{
			return null;
		}

		String cleaned = line.trim();
		if (cleaned.isEmpty())
		{
			return null;
		}

		String[] parts = cleaned.split(":", 4);
		if (parts.length != 3 && parts.length != 4)
		{
			return null;
		}

		List<String> selectors = parseSelectors(parts[0]);
		if (selectors.isEmpty())
		{
			return null;
		}

		List<BankSlotCells.CellRange> cells = BankSlotCells.parse(parts[1]);
		if (cells.isEmpty())
		{
			return null;
		}

		String typeText = parts[2].trim();
		BankSlotStyle style;
		if (BankSlotStyle.isClearType(typeText))
		{
			if (parts.length != 3)
			{
				return null;
			}
			style = null;
		}
		else
		{
			style = BankSlotStyle.parse(typeText, parts.length == 4 ? parts[3] : null);
			if (style == null)
			{
				return null;
			}
		}

		return new BankSlotRule(selectors, cells, style);
	}

	static BankSlotStyle resolve(List<BankSlotRule> rules, BankSlotTarget target)
	{
		BankSlotStyle resolved = null;
		for (BankSlotRule rule : rules)
		{
			if (rule.matches(target))
			{
				resolved = rule.style;
			}
		}
		return resolved;
	}

	static String formatLine(String selector, int cell, BankSlotType type)
	{
		return formatLine(selector, BankSlotCells.single(cell), BankSlotStyle.of(type));
	}

	static String formatLine(String selector, String cells, BankSlotStyle style)
	{
		return selector + ":" + cells + ":" + (style == null ? NONE : style.format());
	}

	private boolean matches(BankSlotTarget target)
	{
		if (!BankSlotCells.contains(cells, target.getCell()))
		{
			return false;
		}

		for (String selector : selectors)
		{
			if (matchesSelector(selector, target))
			{
				return true;
			}
		}
		return false;
	}

	private boolean matchesSelector(String selector, BankSlotTarget target)
	{
		if (WILDCARD.equals(selector))
		{
			return true;
		}
		if (target.isTagTab())
		{
			return TAGS.equals(selector) || selector.equals(target.getSelector());
		}

		return BANK.equals(selector) || selector.equals(target.getSelector());
	}

	private static List<String> parseSelectors(String value)
	{
		List<String> selectors = new ArrayList<>();
		for (String selector : value.split(","))
		{
			String normalized = normalize(selector);
			if (!normalized.isEmpty())
			{
				selectors.add(normalized);
			}
		}
		return selectors;
	}

	static String normalize(String value)
	{
		return Text.standardize(value == null ? "" : value.trim());
	}
}

