		this.plugin = plugin;
		this.textureManager = textureManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.MANUAL);
		setPriority(OverlayPriority.LOW);
		drawAfterLayer(InterfaceID.Bankmain.TABS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget root = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (root == null || root.isHidden() || container == null || container.isHidden())
		{
			return null;
		}

		Widget[] children = plugin.getBankItemWidgets(container);
		if (children == null)
		{
			return null;
		}

		BankGearSlotsPlugin.BankCellResolver resolver = plugin.createBankCellResolver();
		int cell = 0;
		for (Widget widget : children)
		{
			if (!plugin.isVisibleBankCell(widget))
			{
				continue;
			}

			renderWidget(graphics, widget, cell, resolver);
			cell++;
		}

		return null;
	}

	private void renderWidget(Graphics2D graphics, Widget widget, int cell, BankGearSlotsPlugin.BankCellResolver resolver)
	{
		if (!plugin.isVisibleBankCell(widget))
		{
			return;
		}

		BankSlotStyle style = plugin.getRenderedSlotStyle(widget, cell, resolver);
		if (style == null)
		{
			return;
		}

		Rectangle bounds = getSlotBounds(widget);
		if (bounds.isEmpty())
		{
			return;
		}

		Shape clip = graphics.getClip();
		Rectangle viewportBounds = getViewportBounds(widget);
		if (viewportBounds != null && !viewportBounds.isEmpty())
		{
			viewportBounds = new Rectangle(viewportBounds);
			viewportBounds.y -= CLIP_TOP_EXPANSION;
			viewportBounds.height += CLIP_TOP_EXPANSION;
			graphics.clip(viewportBounds);
		}
		try
		{
			BufferedImage texture = textureManager.getTexture(style.getType());
			style.getType().render(graphics, bounds, texture, TEXTURE_SIZE, TEXTURE_ALPHA, style.getTint());
		}
		finally
		{
			graphics.setClip(clip);
		}
	}

	private Rectangle getSlotBounds(Widget widget)
	{
		Rectangle bounds = widget.getBounds();
		if (bounds.isEmpty())
		{
			return bounds;
		}

		return new Rectangle(bounds.x + SLOT_X_OFFSET, bounds.y, Math.min(BANK_ITEM_WIDTH, bounds.width), Math.min(BANK_ITEM_HEIGHT, bounds.height));
	}

	private Rectangle getViewportBounds(Widget widget)
	{
		Rectangle viewport = null;
		for (Widget current = widget.getParent(); current != null; current = current.getParent())
		{
			Rectangle bounds = current.getBounds();
			if (bounds.width <= 0 || bounds.height <= 0)
			{
				continue;
			}

			viewport = viewport == null ? new Rectangle(bounds) : viewport.intersection(bounds);
			if (viewport.isEmpty())
			{
				return viewport;
			}
		}

		return viewport;
	}
}

package com.bankgearslots;

import java.awt.Color;
import java.util.Locale;

final class BankSlotStyle
{
	private static final String NONE = "none";

	private final BankSlotType type;
	private final Color tint;

	private BankSlotStyle(BankSlotType type, Color tint)
	{
		this.type = type;
		this.tint = tint;
	}

	static BankSlotStyle of(BankSlotType type)
	{
		return type == null ? null : new BankSlotStyle(type, null);
	}

	static BankSlotStyle of(BankSlotType type, Color tint)
	{
		return type == null ? null : new BankSlotStyle(type, tint);
	}

	static BankSlotStyle parse(String typeText, String tintText)
	{
		if (isClearType(typeText))
		{
			return null;
		}

		BankSlotType type = BankSlotType.fromConfigKey(typeText);
		if (type == null)
		{
			return null;
		}

		Color tint = parseTint(tintText);
		if (hasText(tintText) && tint == null)
		{
			return null;
		}

		return new BankSlotStyle(type, tint);
	}

	static boolean isClearType(String value)
	{
		return NONE.equals(normalizeType(value));
	}

	BankSlotType getType()
	{
		return type;
	}

	Color getTint()
	{
		return tint;
	}

	BankSlotStyle withType(BankSlotType newType)
	{
		return new BankSlotStyle(newType, tint);
	}

	String format()
	{
		return type.getConfigKey() + (tint == null ? "" : ":" + formatTint(tint));
	}

	private static Color parseTint(String value)
	{
		if (!hasText(value))
		{
			return null;
		}

		String hex = value.trim();
		if (hex.startsWith("#"))
		{
			hex = hex.substring(1);
		}
		if (hex.length() != 6 && hex.length() != 8)
		{
			return null;
		}

		try
		{
			int red = Integer.parseInt(hex.substring(0, 2), 16);
			int green = Integer.parseInt(hex.substring(2, 4), 16);
			int blue = Integer.parseInt(hex.substring(4, 6), 16);
			int alpha = hex.length() == 8 ? Integer.parseInt(hex.substring(6, 8), 16) : 255;
			return new Color(red, green, blue, alpha);
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	private static boolean hasText(String value)
	{
		return value != null && !value.trim().isEmpty();
	}

	private static String normalizeType(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}

	private static String formatTint(Color color)
	{
		if (color.getAlpha() == 255)
		{
			return String.format(Locale.ROOT, "#%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
		}
		return String.format(Locale.ROOT, "#%02x%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue(), color.getAlpha());
	}
}

package com.bankgearslots;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.util.ImageUtil;

enum BankSlotType
{
	HEAD("head", "Head", "Head_slot.png", SpriteID.Wornicons.HEAD),
	CAPE("cape", "Cape", "Cape_slot.png", SpriteID.Wornicons.CAPE),
	NECK("neck", "Neck", "Neck_slot.png", SpriteID.Wornicons.NECK),
	WEAPON("weapon", "Weapon", "Weapon_slot.png", SpriteID.Wornicons.WEAPON),
	TWO_HANDED("two_handed", "Two-handed", "2h_slot.png", SpriteID.Wornicons.WEAPON, true),
	BODY("body", "Body", "Body_slot.png", SpriteID.Wornicons.TORSO),
	SHIELD("shield", "Shield", "Shield_slot.png", SpriteID.Wornicons.SHIELD),
	LEGS("legs", "Legs", "Legs_slot.png", SpriteID.Wornicons.LEGS),
	HANDS("hands", "Hands", "Hands_slot.png", SpriteID.Wornicons.HANDS),
	FEET("feet", "Feet", "Feet_slot.png", SpriteID.Wornicons.FEET),
	RING("ring", "Ring", "Ring_slot.png", SpriteID.Wornicons.RING),
	AMMUNITION("ammunition", "Ammunition", "Ammo_slot.png", SpriteID.Wornicons.AMMUNITION),
	EMPTY_SLOT("empty_slot", "Empty Slot", "empty.png", -1);

	private static final float TINT_LIGHTNESS_INFLUENCE = 0.50f;

	private final String configKey;
	private final String displayName;
	private final String textureResource;
	private final int spriteId;
	private final boolean mirroredSpriteCopy;
	private boolean textureLoadAttempted;
	private BufferedImage texture;
	private BufferedImage tintedTextureSource;
	private final Map<Integer, BufferedImage> tintedTextures = new HashMap<>();

	BankSlotType(String configKey, String displayName, String textureResource, int spriteId)
	{
		this(configKey, displayName, textureResource, spriteId, false);
	}

	BankSlotType(String configKey, String displayName, String textureResource, int spriteId, boolean mirroredSpriteCopy)
	{
		this.configKey = configKey;
		this.displayName = displayName;
		this.textureResource = textureResource;
		this.spriteId = spriteId;
		this.mirroredSpriteCopy = mirroredSpriteCopy;
	}

	String getConfigKey()
	{
		return configKey;
	}

	String getDisplayName()
	{
		return displayName;
	}

	String getTextureResource()
	{
		return textureResource;
	}

	int getSpriteId()
	{
		return spriteId;
	}

	boolean hasSprite()
	{
		return spriteId >= 0;
	}

	boolean hasMirroredSpriteCopy()
	{
		return mirroredSpriteCopy;
	}

	static BankSlotType fromConfigKey(String key)
	{
		if (key == null)
		{
			return null;
		}

		String normalized = normalizeKey(key);
		for (BankSlotType type : values())
		{
			if (normalizeKey(type.configKey).equals(normalized))
			{
				return type;
			}
		}
		return null;
	}

	void render(Graphics2D graphics, Rectangle bounds, BufferedImage slotTexture, int textureSize, int textureAlpha, Color tint)
	{
		if (bounds.width <= 0 || bounds.height <= 0)
		{
			return;
		}

		if (slotTexture != null)
		{
			drawTexture(graphics, bounds, tint == null ? slotTexture : tintedTexture(slotTexture, tint), textureSize, clampAlpha(textureAlpha));
		}
	}

	BufferedImage getFallbackTexture()
	{
		if (textureResource == null)
		{
			return null;
		}
		if (!textureLoadAttempted)
		{
			textureLoadAttempted = true;
			try
			{
				texture = ImageUtil.loadImageResource(BankSlotType.class, textureResource);
			}
			catch (RuntimeException ex)
			{
				texture = null;
			}
		}
		return texture;
	}

	private BufferedImage tintedTexture(BufferedImage image, Color tint)
	{
		if (tintedTextureSource != image)
		{
			tintedTextureSource = image;
			tintedTextures.clear();
		}

		int tintKey = tint.getRGB();
		BufferedImage cached = tintedTextures.get(tintKey);
		if (cached != null)
		{
			return cached;
		}

		BufferedImage tinted = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				tinted.setRGB(x, y, tintPixel(image.getRGB(x, y), tint));
			}
		}
		tintedTextures.put(tintKey, tinted);
		return tinted;
	}

	static int tintPixel(int argb, Color tint)
	{
		int alpha = argb >>> 24;
		if (alpha == 0 || tint == null || tint.getAlpha() == 0)
		{
			return argb;
		}

		int red = (argb >>> 16) & 0xFF;
		int green = (argb >>> 8) & 0xFF;
		int blue = argb & 0xFF;
		float[] tintHsl = rgbToHsl(tint.getRed(), tint.getGreen(), tint.getBlue());
		float[] sourceHsl = rgbToHsl(red, green, blue);
		int colorized = hslToRgb(tintHsl[0], tintHsl[1], tintLightness(sourceHsl[2], tintHsl[2]));
		float strength = tint.getAlpha() / 255.0f;

		return alpha << 24
			| blendChannel(red, (colorized >>> 16) & 0xFF, strength) << 16
			| blendChannel(green, (colorized >>> 8) & 0xFF, strength) << 8
			| blendChannel(blue, colorized & 0xFF, strength);
	}

	private static int blendChannel(int source, int tinted, float strength)
	{
		return Math.max(0, Math.min(255, Math.round(source + (tinted - source) * strength)));
	}

	private static float tintLightness(float sourceLightness, float tintLightness)
	{
		float shift = (tintLightness - 0.5f) * 2.0f * TINT_LIGHTNESS_INFLUENCE;
		if (shift >= 0.0f)
		{
			return sourceLightness + (1.0f - sourceLightness) * shift;
		}
		return sourceLightness * (1.0f + shift);
	}

	private static float[] rgbToHsl(int red, int green, int blue)
	{
		float r = red / 255.0f;
		float g = green / 255.0f;
		float b = blue / 255.0f;
		float max = Math.max(r, Math.max(g, b));
		float min = Math.min(r, Math.min(g, b));
		float lightness = (max + min) / 2.0f;
		float delta = max - min;
		if (delta == 0.0f)
		{
			return new float[] {0.0f, 0.0f, lightness};
		}

		float hue;
		if (max == r)
		{
			hue = 60.0f * (((g - b) / delta) % 6.0f);
		}
		else if (max == g)
		{
			hue = 60.0f * (((b - r) / delta) + 2.0f);
		}
		else
		{
			hue = 60.0f * (((r - g) / delta) + 4.0f);
		}
		if (hue < 0.0f)
		{
			hue += 360.0f;
		}

		float saturation = delta / (1.0f - Math.abs(2.0f * lightness - 1.0f));
		return new float[] {hue, saturation, lightness};
	}

	private static int hslToRgb(float hue, float saturation, float lightness)
	{
		float chroma = (1.0f - Math.abs(2.0f * lightness - 1.0f)) * saturation;
		float h = hue / 60.0f;
		float x = chroma * (1.0f - Math.abs(h % 2.0f - 1.0f));
		float r = 0.0f;
		float g = 0.0f;
		float b = 0.0f;
		if (h < 1.0f)
		{
			r = chroma;
			g = x;
		}
		else if (h < 2.0f)
		{
			r = x;
			g = chroma;
		}
		else if (h < 3.0f)
		{
			g = chroma;
			b = x;
		}
		else if (h < 4.0f)
		{
			g = x;
			b = chroma;
		}
		else if (h < 5.0f)
		{
			r = x;
			b = chroma;
		}
		else
		{
			r = chroma;
			b = x;
		}

		float match = lightness - chroma / 2.0f;
		return toChannel(r + match) << 16
			| toChannel(g + match) << 8
			| toChannel(b + match);
	}

	private static int toChannel(float value)
	{
		return Math.max(0, Math.min(255, Math.round(value * 255.0f)));
	}

	private void drawTexture(Graphics2D graphics, Rectangle bounds, BufferedImage image, int textureSize, int alpha)
	{
		int size = Math.max(1, textureSize);
		int width = size;
		int height = size;
		int x = bounds.x + (bounds.width - width) / 2;
		int y = bounds.y + (bounds.height - height) / 2;

		Composite composite = graphics.getComposite();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, clampAlpha(alpha) / 255.0f));
		graphics.drawImage(image, x, y, width, height, null);
		graphics.setComposite(composite);
	}

	private int clampAlpha(int alpha)
	{
		return Math.max(0, Math.min(255, alpha));
	}

	private static String normalizeKey(String key)
	{
		return key.trim().toLowerCase(Locale.ROOT);
	}
}

