	private final Supplier<Map<Integer, SpritePixels>> spriteOverrides;
	private final IntFunction<BufferedImage> nativeSprites;
	private final Map<BankSlotType, CachedTexture> cache = new EnumMap<>(BankSlotType.class);

	@Inject
	BankSlotTextureManager(Client client, SpriteManager spriteManager)
	{
		this(client::getSpriteOverrides, spriteId -> spriteManager.getSprite(spriteId, 0));
	}

	BankSlotTextureManager(
		Supplier<Map<Integer, SpritePixels>> spriteOverrides,
		IntFunction<BufferedImage> nativeSprites)
	{
		this.spriteOverrides = spriteOverrides;
		this.nativeSprites = nativeSprites;
	}

	BufferedImage getTexture(BankSlotType type)
	{
		Map<Integer, SpritePixels> overrides = spriteOverrides.get();
		SpritePixels tileOverride = overrides == null ? null : overrides.get(SLOT_TILE_SPRITE_ID);
		SpritePixels iconOverride = overrides == null || !type.hasSprite()
			? null
			: overrides.get(type.getSpriteId());

		if (tileOverride == null && iconOverride == null)
		{
			cache.remove(type);
			return type.getFallbackTexture();
		}

		CachedTexture cached = cache.get(type);
		if (cached != null && cached.matches(tileOverride, iconOverride))
		{
			return cached.texture;
		}

		boolean cacheable = true;
		BufferedImage tile = tileOverride == null
			? nativeSprites.apply(SLOT_TILE_SPRITE_ID)
			: toBufferedImage(tileOverride);
		if (tile == null)
		{
			tile = BankSlotType.EMPTY_SLOT.getFallbackTexture();
			cacheable = false;
		}
		if (tile == null)
		{
			return type.getFallbackTexture();
		}

		BufferedImage icon = null;
		if (type.hasSprite())
		{
			icon = iconOverride == null
				? nativeSprites.apply(type.getSpriteId())
				: toBufferedImage(iconOverride);
			if (icon == null)
			{
				return type.getFallbackTexture();
			}
		}

		BufferedImage texture = compose(tile, icon, type.hasMirroredSpriteCopy());
		if (cacheable)
		{
			cache.put(type, new CachedTexture(tileOverride, iconOverride, texture));
		}
		else
		{
			cache.remove(type);
		}
		return texture;
	}

	static BufferedImage compose(BufferedImage tile, BufferedImage icon, boolean addMirroredIcon)
	{
		BufferedImage texture = new BufferedImage(tile.getWidth(), tile.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = texture.createGraphics();
		try
		{
			graphics.drawImage(tile, 0, 0, null);
			if (icon != null)
			{
				int x = (tile.getWidth() - icon.getWidth()) / 2;
				int y = (tile.getHeight() - icon.getHeight()) / 2;
				graphics.drawImage(icon, x, y, null);
				if (addMirroredIcon)
				{
					graphics.drawImage(icon, x + icon.getWidth(), y, -icon.getWidth(), icon.getHeight(), null);
				}
			}
		}
		finally
		{
			graphics.dispose();
		}
		return texture;
	}

	private static BufferedImage toBufferedImage(SpritePixels sprite)
	{
		try
		{
			return sprite.toBufferedImage();
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	private static final class CachedTexture
	{
		private final SpritePixels tileOverride;
		private final SpritePixels iconOverride;
		private final BufferedImage texture;

		private CachedTexture(SpritePixels tileOverride, SpritePixels iconOverride, BufferedImage texture)
		{
			this.tileOverride = tileOverride;
			this.iconOverride = iconOverride;
			this.texture = texture;
		}

		private boolean matches(SpritePixels tileOverride, SpritePixels iconOverride)
		{
			return this.tileOverride == tileOverride && this.iconOverride == iconOverride;
		}
	}
}
